Review this change for security vulnerabilities.

Changed files (you may Read these and any other file in the repo):
  - lib/generator/__tests__/season.test.ts
  - lib/generator/season.ts

Unified diff (only + lines are new):

=== DIFF: lib/generator/__tests__/season.test.ts ===
@@ -0,0 +1,43 @@
+import { currentSeason, inSeason, seasonFit } from "../season";
+
+test("matches case-insensitively — the DB stores Title case, fixtures use lower", () => {
+  expect(inSeason(["Winter"], "winter")).toBe(true);
+  expect(inSeason(["spring"], "Spring")).toBe(true);
+});
+
+test("an item tagged for other seasons is out of season", () => {
+  expect(inSeason(["Spring", "Summer", "Autumn"], "Winter")).toBe(false);
+});
+
+test("an untagged item is never penalised — no tags means no opinion", () => {
+  expect(inSeason([], "Winter")).toBe(true);
+  expect(inSeason(undefined, "Winter")).toBe(true);
+});
+
+test("with no season context nothing is out of season", () => {
+  expect(inSeason(["Summer"], undefined)).toBe(true);
+});
+
+test("seasonFit is the fraction of pieces that suit the season", () => {
+  const items = [
+    { seasons: ["Winter"] },
+    { seasons: ["Winter"] },
+    { seasons: ["Summer"] },
+    { seasons: ["Summer"] },
+  ];
+  expect(seasonFit(items, "Winter")).toBe(0.5);
+  expect(seasonFit([{ seasons: ["Winter"] }], "Winter")).toBe(1);
+  expect(seasonFit([{ seasons: ["Summer"] }], "Winter")).toBe(0);
+});
+
+test("seasonFit of an empty combo is 1, not NaN", () => {
+  expect(seasonFit([], "Winter")).toBe(1);
+});
+
+test("currentSeason maps months to Title-case seasons", () => {
+  expect(currentSeason(new Date("2026-01-15T12:00:00Z"))).toBe("Winter");
+  expect(currentSeason(new Date("2026-03-15T12:00:00Z"))).toBe("Spring");
+  expect(currentSeason(new Date("2026-07-15T12:00:00Z"))).toBe("Summer");
+  expect(currentSeason(new Date("2026-10-15T12:00:00Z"))).toBe("Autumn");
+  expect(currentSeason(new Date("2026-12-15T12:00:00Z"))).toBe("Winter");
+});


=== DIFF: lib/generator/season.ts ===
@@ -0,0 +1,44 @@
+/**
+ * Season is a PREFERENCE, not an eligibility gate.
+ *
+ * A hard season filter ran against every REQUIRED slot, so one narrowly-tagged
+ * category could zero the entire result. Measured on a constructed closet — 10
+ * tops, 4 bottoms, 4 shoes, every piece wearable, the trousers simply lacking a
+ * Winter tag — the same wardrobe produced 40 combos in summer and 0 in winter,
+ * with `missingCategory` blaming Bottoms. Outerwear and the Refine colour lean
+ * both moved to the soft-preference model for exactly this reason; season now
+ * follows them — it orders candidates and weights the score, and can never
+ * eliminate one.
+ *
+ * The MEASURED signal still filters hard (`weatherRules`: rain excludes suede,
+ * cold adds a layer). That is a real reading of the day. A season tag is a
+ * coarse label derived from the calendar month, which is a much blunter
+ * instrument and does not deserve veto power.
+ */
+
+/**
+ * Does this item suit the season?
+ *
+ * Case-insensitive on purpose: the DB and the AI tagger store Title case
+ * ("Winter", `lib/ai/tagging-schema.ts`) while the generator's test fixtures use
+ * lower case. An untagged item counts as in-season — absence of tags is absence
+ * of an opinion, not a reason to rank it last.
+ */
+export function inSeason(seasons: string[] | undefined, season: string | undefined): boolean {
+  if (!season) return true;
+  if (!seasons || seasons.length === 0) return true;
+  const s = season.toLowerCase();
+  return seasons.some((x) => x.toLowerCase() === s);
+}
+
+/** The fraction of a combo's pieces that suit the season. 1 = all of them. */
+export function seasonFit(items: { seasons?: string[] }[], season: string | undefined): number {
+  if (!items.length) return 1;
+  return items.filter((i) => inSeason(i.seasons, season)).length / items.length;
+}
+
+/** Title case to match the DB tag vocabulary. */
+export function currentSeason(d: Date): string {
+  const m = d.getMonth();
+  return m < 2 || m === 11 ? "Winter" : m < 5 ? "Spring" : m < 8 ? "Summer" : "Autumn";
+}


Investigate per the method in your instructions, then return the findings list.

